1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls } from '../core/renderer';
6	import { cam, keys } from '../views/state';
7	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
8	import { exBuildGlider, exPlaceGlider } from './glider';
9	import { exChase } from './chase';
10	import { exShowChooser } from './chooser';
11	
12	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
13	
14	let glider: THREE.Group | null = null;
15	let state: GliderState | null = null;
16	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
17	
18	const active = () => cam.mode === 'glider' && state !== null;
19	
20	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
21	function exShowSpeed(): void {
22	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
23	  if (t === readout) return;
24	  readout = t;
25	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
26	}
27	
28	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
29	function advance(dt: number, inp: GliderInput): void {
30	  exStep(state!, inp, dt);
31	  exPlaceGlider(glider!, state!);
32	  exChase(camera, controls.target, state!, dt);
33	  exShowSpeed();
34	}
35	
36	export const explore = {
37	  active,
38	  get state() { return state; },
39	  get glider() { return glider; },
40	  start(): void {
41	    state = exCreate();
42	    if (!glider) glider = exBuildGlider();
43	    if (!glider.parent) scene.add(glider);
44	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
45	    exPlaceGlider(glider, state);
46	    exChase(camera, controls.target, state, 0, true);
47	    exShowSpeed();
48	    document.body.classList.add('explore');
49	  },
50	  update(dt: number): void {
51	    if (!active()) return;
52	    advance(dt, exInputFromKeys(keys, _inp));
53	  },
54	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
55	  step(dt: number, inp: GliderInput): void {
56	    if (active()) advance(dt, inp);
57	  },
58	  exit(): void {
59	    const u = new URL(location.href);
60	    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
61	    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
62	    else location.replace(u.toString());
63	  },
64	};
65	
66	export function setupExplore(): void {
67	  window.addEventListener('keydown', (e) => {
68	    if (!active()) return;
69	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
70	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
71	    const t = e.target as HTMLElement | null;
72	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
73	    const k = e.key.toLowerCase(); keys.add(k);
74	    if (k.startsWith('arrow')) e.preventDefault();
75	  });
76	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
77	  for (const id of ['langSelect', 'qualitySel']) {
78	    const sel = document.getElementById(id); if (!sel) continue;
79	    let byMouse = false;
80	    sel.addEventListener('pointerdown', () => { byMouse = true; });
81	    sel.addEventListener('keydown', () => { byMouse = false; });
82	    sel.addEventListener('change', () => { if (byMouse && active()) sel.blur(); byMouse = false; });
83	  }
84	  const q = new URLSearchParams(location.search);
85	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
86	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
87	  if (q.get('explore') === 'glider') { explore.start(); return; }
88	  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
89	}
90

1	import { clamp, smooth } from '../../common/math';
2	import type { SongHanConfig } from '../../config';
3	
4	/* [swingController] state machine quay cầu, phát event swingStart / swingOpen / swingClosed / stateChange */
5	export const SWING_STATES = ['CLOSED', 'STOP_TRAFFIC', 'UNLOCK', 'ROTATING_OPEN', 'OPEN', 'ROTATING_CLOSE', 'LOCK', 'REOPEN_TRAFFIC'] as const;
6	export type SwingState = typeof SWING_STATES[number];
7	export type Signal = 'green' | 'amber' | 'red';
8	
9	/* Vận tốc góc hình thang: tăng dần – đều – giảm dần (a = phần thời gian tăng/giảm tốc) */
10	function trapezoidEase(u: number, a = 0.22) {
11	  u = clamp(u, 0, 1); const vmax = 1 / (1 - a);
12	  if (u < a) return vmax * u * u / (2 * a);
13	  if (u < 1 - a) return vmax * (u - a / 2);
14	  return 1 - vmax * (1 - u) * (1 - u) / (2 * a);
15	}
16	export class SwingController extends EventTarget {
17	  cfg: SongHanConfig;
18	  state: SwingState = 'CLOSED';
19	  t = 0;
20	  speed = 30;                     // hệ số tăng tốc so với thời gian thật
21	  angle = 0; lift = 0; pin = 1; barrier = 0;
22	  signal: Signal = 'green';
23	  closeAsked = false;
24	  fromTour = false;               // quay do Tour kích hoạt: đóng ngay khi tàu buồm qua hết luồng
25	  spanClear: () => boolean = () => true;
26	  canClose: () => boolean = () => true;
27	  canStart: () => boolean = () => true;     // thời tiết (bão) gán predicate; false → start() từ chối và phát 'swingBlocked'
28	
29	  constructor(cfg: SongHanConfig) {
30	    super();
31	    this.cfg = cfg;
32	  }
33	  get busy() { return this.state !== 'CLOSED'; }
34	  get allowEntry() { return this.state === 'CLOSED' || (this.state === 'REOPEN_TRAFFIC' && this.signal === 'green'); }
35	  start(speed?: number) {
36	    if (this.state !== 'CLOSED') return false;
37	    if (!this.canStart()) { this.dispatchEvent(new Event('swingBlocked')); return false; }
38	    if (speed) this.speed = speed;
39	    this.go('STOP_TRAFFIC'); this.dispatchEvent(new Event('swingStart'));
40	    return true;
41	  }
42	  requestClose() { if (this.state === 'OPEN') this.closeAsked = true; }
43	  go(s: SwingState) {
44	    this.state = s; this.t = 0;
45	    if (s === 'OPEN') this.closeAsked = false;
46	    this.dispatchEvent(new CustomEvent<SwingState>('stateChange', { detail: s }));
47	    if (s === 'OPEN') this.dispatchEvent(new Event('swingOpen'));
48	    if (s === 'CLOSED') this.dispatchEvent(new Event('swingClosed'));
49	  }
50	  update(dt: number) {
51	    if (this.state === 'CLOSED') return;
52	    const T = this.cfg.timing, rot = Math.PI / 2 * this.cfg.rotateDir;
53	    this.t += dt * this.speed;
54	    const k = (d: number) => clamp(this.t / d, 0, 1);
55	    switch (this.state) {
56	      case 'STOP_TRAFFIC':
57	        this.signal = this.t < T.amber ? 'amber' : 'red';
58	        this.barrier = smooth(clamp((this.t - T.amber) / T.barrier, 0, 1));
59	        if (this.t > T.amber + T.barrier && (this.spanClear() || this.t > T.stopMax)) this.go('UNLOCK');
60	        break;
61	      case 'UNLOCK': {            // rút chốt rồi nâng nhẹ nhịp khỏi gối đầu cánh
62	        const u = k(T.unlock);
63	        this.pin = 1 - smooth(clamp(u * 2, 0, 1)); this.lift = smooth(clamp(u * 2 - 1, 0, 1)) * this.cfg.lift;
64	        if (u >= 1) this.go('ROTATING_OPEN');
65	        break;
66	      }
67	      case 'ROTATING_OPEN':
68	        this.angle = trapezoidEase(k(T.rotate)) * rot;
69	        if (k(T.rotate) >= 1) this.go('OPEN');
70	        break;
71	      case 'OPEN':
72	        if ((this.t > T.openHold || this.closeAsked) && this.canClose()) this.go('ROTATING_CLOSE');
73	        break;
74	      case 'ROTATING_CLOSE':
75	        this.angle = (1 - trapezoidEase(k(T.rotate))) * rot;
76	        if (k(T.rotate) >= 1) { this.angle = 0; this.go('LOCK'); }
77	        break;
