13	/* Cầu sông Hàn: nút quay, tốc độ, trạng thái, camera theo dõi, lịch tự quay theo giờ Việt Nam */
14	export let swingRender = () => {};
15	export function setupSwingUI(songHan: SongHanBridge, toggle: Toggle) {
16	  const ctrl = songHan.ctrl;
17	  const btn = document.getElementById('btnSwing') as HTMLButtonElement, stateEl = document.getElementById('swingState'), speedSel = document.getElementById('swingSpeed') as HTMLSelectElement;
18	  let follow = true, saved: ViewPreset | null = null;
19	  swingRender = () => {
20	    stateEl.textContent = t('st_' + ctrl.state);
21	    btn.textContent = t(ctrl.state === 'CLOSED' ? 'swingBtn' : ctrl.state === 'OPEN' ? 'swingClose' : 'swingBusy');
22	    btn.disabled = !(ctrl.state === 'CLOSED' || ctrl.state === 'OPEN');
23	  };
24	  btn.addEventListener('click', () => { if (ctrl.state === 'CLOSED') ctrl.start(Number(speedSel.value)); else ctrl.requestClose(); });
25	  speedSel.addEventListener('change', () => { ctrl.speed = Number(speedSel.value); });
26	  toggle('btnSwingFollow', (on) => { follow = on; });
27	  toggle('btnShLife', (on) => songHan.setLifeVisible(on));
28	  toggle('btnShPeople', (on) => songHan.setPeopleVisible(on));
29	  ctrl.addEventListener('stateChange', (e) => {
30	    const s = (e as CustomEvent<SwingState>).detail;
31	    swingRender(); audio.motor(s === 'ROTATING_OPEN' || s === 'ROTATING_CLOSE');
32	    if (s === 'OPEN' && ctrl.fromTour) ctrl.requestClose();    // trong Tour: đóng ngay khi tàu buồm qua hết luồng
33	    if (s === 'CLOSED') ctrl.fromTour = false;
34	  });
35	  // Tour Cầu sông Hàn tới điểm "trên trụ quay" thì tự quay cầu ở 30×
36	  setTourSwingHook(() => { if (ctrl.state === 'CLOSED') { speedSel.value = '30'; ctrl.fromTour = true; if (!ctrl.start(30)) ctrl.fromTour = false; } });
37	  // Bão: không quay cầu (cấm theo thông báo của thành phố) — hiện lý do vài giây rồi trả lại dòng trạng thái
38	  let blockedT = 0;
39	  ctrl.addEventListener('swingBlocked', () => {
40	    if (ctrl.fromTour) { const tx = document.getElementById('tourText'); tx.textContent = `${tx.textContent} ${t('wxSwingTour')}`; }   // Tour: bỏ bước quay, ghi chú thích
41	    stateEl.textContent = t('swingWeather'); clearTimeout(blockedT); blockedT = window.setTimeout(swingRender, 4000); });
42	  ctrl.addEventListener('swingStart', () => {
43	    audio.horn();
44	    if (follow && cam.mode !== 'tour' && cam.flight.then !== 'tour') {
45	      saved = { pos: camera.position.toArray(), target: controls.target.toArray() }; exitTour(); flyTo(VIEWS.shSwingCam);
46	    }
47	  });
48	  ctrl.addEventListener('swingClosed', () => { audio.horn(); if (follow && saved && cam.mode !== 'tour') flyTo(saved); saved = null; });
49	  // tự quay lúc 23:00 thứ Bảy, Chủ nhật theo giờ Việt Nam (UTC+7) nếu trang đang mở; chạy tốc độ thật 1×
50	  let lastAuto = '';
51	  setInterval(() => {
52	    const A = CONFIG.songHan.autoSchedule, now = new Date(Date.now() + A.utcOffset * 3600e3), key = now.toISOString().slice(0, 10);
53	    if (A.days.includes(now.getUTCDay()) && now.getUTCHours() === A.hour && now.getUTCMinutes() < 10 && lastAuto !== key && ctrl.state === 'CLOSED') {
54	      lastAuto = key; speedSel.value = '1'; ctrl.start(1);
55	    }
56	  }, 20000);
57	  swingRender();
58	}
