41	  constructor() {
42	    super('SongHanBridge', 'sh', SH.z, new THREE.Vector3(0, 15, SH.z), SH.lodDistance);
43	    this.mats = shMaterials();
44	    this.farDistance = SH.farDistance;
45	    shBuildFixedSpans(this);
46	    shBuildTurntable(this);
47	    shBuildSwingSpan(this);
48	    shBuildSignals(this);
49	    shBuildLife(this);
50	    this.finalize();
51	    // lề bộ hành, người đi bộ… (lớp không phản chiếu) cũng ẩn khi camera ở rất xa
52	    for (const o of this.noReflect) if (!this.farHide.includes(o)) this.farHide.push(o);
53	    this.ctrl = new SwingController(SH);
54	    // nhịp quay chỉ mở khóa khi không còn xe trên đó; chỉ đóng khi tàu cao đã qua hết luồng
55	    this.ctrl.spanClear = () => !this.traffic.list.some((v) => Math.abs(v.s) < SH.barrierX);
56	    this.ctrl.canClose = () => Math.abs(this.ship.z - this.ship.target) < 0.5;
57	    this.ctrl.addEventListener('stateChange', (e) => {
58	      const s = (e as CustomEvent<SwingState>).detail;
59	      if (s === 'UNLOCK') for (const v of this.traffic.list) if (Math.abs(v.s) < SH.barrierX) v.s = v.dir > 0 ? SH.barrierX + 6 : -SH.barrierX - 6;
60	      if (s === 'OPEN') { this.ship.target = -this.ship.target; }       // tàu cao chạy qua luồng sang phía bên kia
61	    });
62	    this.hideBankTrees();
63	  }
64	  /* Ẩn vài cây ven kè nằm dưới đường dẫn hai đầu cầu (không đổi chuỗi ngẫu nhiên của khu cây) */
65	  hideBankTrees() {
66	    const mats = new Set<THREE.Material>([MAT.trunk, MAT.leaf, MAT.palm]), m = new THREE.Matrix4(), p = new THREE.Vector3(), zero = new THREE.Matrix4().makeScale(0, 0, 0);
67	    scene.traverse((obj) => {
68	      const o = obj as THREE.InstancedMesh;
69	      if (!o.isInstancedMesh || !mats.has(o.material as THREE.Material)) return;
70	      for (let i = 0; i < o.count; i++) {
71	        o.getMatrixAt(i, m); p.setFromMatrixPosition(m);
72	        if (Math.abs(p.z - SH.z) < SH.hw + 4 && Math.abs(p.x) > 250 && Math.abs(p.x) < 300) o.setMatrixAt(i, zero);
73	      }
74	      o.instanceMatrix.needsUpdate = true;
75	    });
76	  }
77	  setPeopleVisible(on: boolean) { this.peopleOn = on; }
78	  update(dt: number, elapsed: number, cam: THREE.Camera) {
79	    const near = this.updateLod(cam);
80	    const ctrl = this.ctrl;
81	    ctrl.update(dt);
82	    // xoay nhịp quay quanh tâm trụ (+ nâng nhẹ khi mở khóa); con lăn quay theo
83	    const prev = this.swing.rotation.y;
84	    this.swing.rotation.y = ctrl.angle; this.swing.position.y = ctrl.lift;
85	    if (prev !== ctrl.angle) { this.rollerSpin += (ctrl.angle - prev) * SH.railR / 0.33; if (this.details.visible) shPlaceRollers(this, this.rollerSpin); }
86	    this.swingDetails.visible = this.details.visible;
87	    if (this.details.visible) shUpdateSignals(this, ctrl, elapsed);   // barie, đèn tín hiệu, đèn hàng hải, chốt: đều trong details / swingDetails
88	    const n = shared.uNight.value;
89	    this.mats.crown.emissiveIntensity = n * 2.2; this.mats.drumLight.emissiveIntensity = n * 2.0; this.mats.porthole.emissiveIntensity = n * 0.8;
90	    this.people.group.visible = this.peopleOn && this.details.visible;
91	    if (this.people.group.visible) stepPeople(this.people, dt, elapsed);
92	    // tàu cao di chuyển theo hệ số tăng tốc của kịch bản quay
93	    const S = this.ship;
94	    if (S.z !== S.target) {
95	      const step = S.speed * dt * ctrl.speed * Math.sign(S.target - S.z);
96	      S.z = Math.abs(S.target - S.z) <= Math.abs(step) ? S.target : S.z + step;
97	      S.obj.position.z = S.z; S.obj.rotation.y = S.target > 0 ? 0 : Math.PI;
98	    }
99	    if (!near) return;
100	    shStepTraffic(this.traffic, dt, ctrl);
101	    stepBoats(this.boats, dt, elapsed, -1850, 1150);
102	  }
103	}
